import{z as i,x as B,o as E,c as d,q as r,j as s,D as o,d as e,s as A,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"MCS 锁","description":"","frontmatter":{"title":"MCS 锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mcs-lock.md","filePath":"cs/mcs-lock.md","lastUpdated":1791063341000}'),c={name:"cs/mcs-lock.md"};function p(m,a,C,S,u,h){const l=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="mcs-锁" tabindex="-1">MCS 锁 <a class="header-anchor" href="#mcs-锁" aria-label="Permalink to &quot;MCS 锁&quot;">​</a></h1><div class="epigraph"><p>每位等待者在自己的结点上自旋，只在前驱释放时被打醒；于是锁争用不再变成所有核对同一 cache 行的轮番失效。</p><footer>—— 据 Mellor-Crummey and Scott, Algorithms for Scalable Synchronization, TOCS 1991 整理</footer></div><p><a href="/cs/spinlock">上一课</a>的 TAS 锁让所有核打同一锁字，MESI 行在核间弹跳，核数上升后获取延迟爆炸。缺口是 <strong>MCS</strong>（或同类排队锁）：每个 CPU 一个队列结点，自旋在<strong>本地标志</strong>上，释放者只写后继的标志。本课钉这个结构，不把每一种公平锁变体写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全局锁字是共享热点。<a href="/cs/atomic-rmw">原子 RMW</a> 无法取消「大家都要看见锁状态」这一事实，但可以把「我是否轮到」放到每核私有行上。MCS：入队用 CAS 把 <code>tail</code> 指到自己的结点并链上前驱；若有前驱则在自己的 <code>locked</code> 上自旋。释放：若无后继则 CAS 清 <code>tail</code>，否则写后继 <code>locked=0</code>。缺口不是关 IRQ 的纪律（仍然要），而是<strong>等待的局部性</strong>。</p><p><span class="marginnote">直觉类比：TAS 锁像一屋子人挤在门口盯同一块牌子，牌一翻全场一起扑；MCS 像银行取号——每人低头等自己的号被叫，柜员办完只喊下一位，队伍里其余人互不打扰。</span></p><p><span class="marginnote">结点必须在入队期间保持地址稳定，通常是栈上局部量或 per-CPU 结点。持锁时不能睡，与普通自旋相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>获取：初始化本结点，原子交换进尾，链好，自旋本地。释放：看后继指针；若空则尝试把尾从自己 CAS 成空；有后继则 store 其标志。公平：队列 FIFO，无饥饿于「后来者插到 TAS 成功」那种。与<a href="/cs/kernel-preempt">内核抢占</a>：持 MCS 仍关抢占。</p>',9)),(E(),s(n,null,{default:o(()=>[A(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAIL%5B%22%E5%85%A8%E5%B1%80%E5%8F%AA%E4%B8%80%E4%B8%AA%20tail%22%5D%20--%3E%20N1%5B%22%E7%BB%93%E7%82%B9%3A%20%E6%9C%AC%E5%9C%B0%E8%87%AA%E6%97%8B%22%5D%0A%20%20N1%20--%3E%20N2%5B%22%E5%90%8E%E7%BB%A7%E7%BB%93%E7%82%B9%22%5D%0A%20%20REL%5B%22%E9%87%8A%E6%94%BE%22%5D%20--%3E%20WAKE%5B%22%E5%8F%AA%E5%86%99%E5%90%8E%E7%BB%A7%E6%A0%87%E5%BF%97%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("Linux "),t("code",null,"qspinlock"),e(" 是压缩版直觉近亲，主干不转写源码。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("MCS 把 RMW 热点收成对 "),t("code",null,"tail"),e(" 的短 CAS，长等待发生在私有行上，扩展性好。它不缩短临界区：临界区仍须短。也不允许睡眠：队列结点在栈上，睡了栈可能被别的路径复用。用户态长时间等待仍应进 futex，而不是 MCS 空转一个量子。")],-1)),a[6]||(a[6]=t("p",null,"两种锁的等待发生在哪里，是扩展性差距的全部来源：",-1)),(E(),s(n,null,{default:o(()=>[A(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20TAS%5B%22TAS%20%E9%94%81%EF%BC%9AN%20%E4%B8%AA%E6%A0%B8%22%5D%20--%3E%20HOT%5B%22%E5%85%A8%E9%83%A8%E8%87%AA%E6%97%8B%E5%90%8C%E4%B8%80%E9%94%81%E5%AD%97%22%5D%0A%20%20HOT%20--%3E%20PING%5B%22cache%20%E8%A1%8C%E6%A0%B8%E9%97%B4%E5%BC%B9%E8%B7%B3%22%5D%0A%20%20PING%20--%3E%20SLOW%5B%22%E6%A0%B8%E8%B6%8A%E5%A4%9A%E8%B6%8A%E6%85%A2%22%5D%0A%20%20MCS%5B%22MCS%EF%BC%9AN%20%E4%B8%AA%E6%A0%B8%E6%8E%92%E9%98%9F%22%5D%20--%3E%20OWN%5B%22%E5%90%84%E8%87%AA%E8%87%AA%E6%97%8B%E6%9C%AC%E5%9C%B0%E7%BB%93%E7%82%B9%22%5D%0A%20%20OWN%20--%3E%20WAKE%5B%22%E9%87%8A%E6%94%BE%E5%8F%AA%E5%86%99%E5%90%8E%E7%BB%A7%E4%B8%80%E4%BA%BA%22%5D%0A%20%20WAKE%20--%3E%20FAST%5B%22%E4%BA%89%E7%94%A8%E4%B8%8D%E9%9A%8F%E6%A0%B8%E6%95%B0%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：10 个核抢一把 TAS 锁，锁字那一行 cache 每次易手都要跨核失效一轮，一次几百纳秒，核越多轮得越密；MCS 下等待各自发生在私有行上，跨核流量只剩 tail 上的一次 CAS 与后继结点行上的一次写。</span></p><p><span class="marginnote">常见误区：初学者容易以为换上排队锁临界区就变快。MCS 只解决「等待时互踩」，临界区该多短仍要短；等得久也照样不该原地空转——该睡就交给下一课的 mutex，把 CPU 让出去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 CLH、K42 锁的全部比较写成综述。NUMA 上还可再分层（本地队列再全局），那是工程，对象仍是排队。mutex 如何在拿不到时睡，下一课。</p><p>后课默认：多核短临界区可用排队自旋。线程上下文里等得久应让出 CPU，下一课 mutex 与休眠。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MCS：本地自旋、FIFO 排队，减轻锁字乒乓。</li><li>仍禁睡眠、临界区仍短。</li><li>可睡眠互斥是下一课。</li><li>出处：Mellor-Crummey and Scott, <em>TOCS</em> 1991；Love, <em>LKD</em>。</li></ul>',7))])}const M=i(c,[["render",p]]);export{T as __pageData,M as default};
